challenges.starter:
function totalPrice(json) {
  // JSON.parse, then add price * qty
}

challenges.solution:
function totalPrice(json) {
  try {
    return JSON.parse(json).reduce((sum, item) => sum + item.price * item.qty, 0);
  } catch (error) {
    return 0;
  }
}

challenges.starter:
function toggle(tasks, id) {
  // return a new array; use map and the spread operator
}

challenges.solution:
function toggle(tasks, id) {
  return tasks.map((t) => (t.id === id ? { ...t, done: !t.done } : t));
}

challenges.starter:
function search(items, query) {
  // filter by name
}

challenges.solution:
function search(items, query) {
  const q = query.toLowerCase();
  return items.filter((item) => item.name.toLowerCase().includes(q));
}
